create or replace function public.ils_professional_assignment_creation_gate(p_work_item_id uuid,p_work_stream text,p_professional_user_id uuid,p_work_code text) returns boolean language sql security definer stable set search_path=public as $$ select case when auth.uid() is null or auth.uid() <> p_professional_user_id then false when p_work_item_id is null or p_work_stream not in ('PROFESSIONAL','B2B') or p_work_code is null then false when not exists(select 1 from public.ils_unified_assignment_decisions u join public.ils_work_capability_requirements r on r.work_code=u.work_code and r.active=true where u.work_code=p_work_code and u.associate_user_id=p_professional_user_id and u.decision='ALLOW' and u.requires_professional_review=false and u.requires_supervision=false and exists(select 1 from public.ils_associate_trust_profiles t where t.user_id=p_professional_user_id and t.profile_status='ACTIVE' and t.identity_verified=true and t.qualification_verified=true and t.professional_registration_verified=true and t.capability_verified=true) and exists(select 1 from public.ils_associate_capabilities c where c.user_id=p_professional_user_id and c.status='VERIFIED' and c.verified_at is not null and c.capability_code = any(select jsonb_array_elements_text(r.required_capabilities)))) then false when p_work_stream='PROFESSIONAL' then exists(select 1 from public.ils_professional_work_items w where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) when p_work_stream='B2B' then exists(select 1 from public.ils_b2b_work_items w where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) else false end $$; revoke all on function public.ils_professional_assignment_creation_gate(uuid,text,uuid,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_creation_gate(uuid,text,uuid,text) to authenticated;